import java.util.TreeMap;

public class Words {
    public static TreeMap<String, Integer> wordCounts(String text) {
        TreeMap<String, Integer> counts = new TreeMap<>();
        for (String w : text.toLowerCase().split("\\s+")) {
            if (!w.isEmpty()) counts.put(w, counts.getOrDefault(w, 0) + 1);
        }
        return counts;
    }
}

