exercises.solution:
import java.util.HashMap;
import java.util.Map;

public class Translate {
    static final Map<String, String> SW = new HashMap<>(Map.of("water", "maji", "good", "nzuri", "food", "chakula", "school", "shule", "friend", "rafiki"));

    public static String translate(String sentence) {
        String[] w = sentence.trim().split("\\s+");
        for (int i = 0; i < w.length; i++) w[i] = SW.getOrDefault(w[i].toLowerCase(), w[i]);
        return String.join(" ", w);
    }
}
